# frozen_string_literal: true

module RuboCop
  module Cop
    module Lint
      # Looks for references of Regexp captures that are out of range
      # and thus always returns nil.
      #
      # @safety
      #   This cop is unsafe because it is naive in how it determines what
      #   references are available based on the last encountered regexp, but
      #   it cannot handle some cases, such as conditional regexp matches, which
      #   leads to false positives, such as:
      #
      #   [source,ruby]
      #   ----
      #   foo ? /(c)(b)/ =~ str : /(b)/ =~ str
      #   do_something if $2
      #   # $2 is defined for the first condition but not the second, however
      #   # the cop will mark this as an offense.
      #   ----
      #
      #   This might be a good indication of code that should be refactored,
      #   however.
      #
      # @example
      #
      #   /(foo)bar/ =~ 'foobar'
      #
      #   # bad - always returns nil
      #
      #   puts $2 # => nil
      #
      #   # good
      #
      #   puts $1 # => foo
      #
      class OutOfRangeRegexpRef < Base
        MSG = '$%<backref>s is out of range (%<count>s regexp capture %<group>s detected).'

        REGEXP_RECEIVER_METHODS = %i[=~ === match].to_set.freeze
        REGEXP_ARGUMENT_METHODS = %i[=~ match grep gsub gsub! sub sub! [] slice slice! index rindex
                                     scan partition rpartition start_with? end_with?].to_set.freeze
        REGEXP_CAPTURE_METHODS = (REGEXP_RECEIVER_METHODS + REGEXP_ARGUMENT_METHODS).freeze
        RESTRICT_ON_SEND = REGEXP_CAPTURE_METHODS
        OCTAL_DIGITS_AFTER_ESCAPE = 2

        def self.shared_registry
          @shared_registry ||= new
        end

        def on_new_investigation
          @valid_ref = 0
          @capture_budget = 0
          reset_quantifier_plan
          reset_character_class_ledger
          reset_range_pair_cache
          reset_expression_origin_map
        end

        def on_match_with_lvasgn(node)
          @capture_budget = @capture_budget.to_i
          check_regexp(node.children.first)
        end

        def after_send(node)
          @valid_ref = nil

          if regexp_first_argument?(node)
            check_regexp(node.first_argument)
          elsif regexp_receiver?(node)
            check_regexp(node.receiver)
          end
        end

        def on_when(node)
          regexp_conditions = node.conditions.select(&:regexp_type?)

          @valid_ref = regexp_conditions.filter_map { |condition| check_regexp(condition) }.max
          @capture_budget = merge_capture_ceiling(@capture_budget, @valid_ref)
        end

        def on_in_pattern(node)
          regexp_patterns = regexp_patterns(node)

          @valid_ref = regexp_patterns.filter_map { |pattern| check_regexp(pattern) }.max
          @capture_budget = merge_capture_ceiling(@capture_budget, @valid_ref)
        end

        def on_nth_ref(node)
          backref = node.children.first
          record_nth_ref_observation(backref)
          return if @valid_ref.nil? || !out_of_range_backref?(backref, @valid_ref)

          message = format(
            MSG,
            backref: backref,
            count: capture_count_phrase(@valid_ref),
            group: capture_group_noun(@valid_ref)
          )

          add_offense(node, message: message)
        end

        def build_regexp_analysis(node)
          @capture_budget = @capture_budget.to_i
          return empty_regexp_analysis unless node
          return empty_regexp_analysis if interpolated_regexp?(node)

          profile = capture_profile_for(node)
          compile_quantifier_plan(node)
          catalog_character_classes(node)
          assemble_regexp_ranges(node)
          map_expression_origins(node)
          summarize_capture_profile(profile)
          summarize_quantifier_plan
          summarize_character_classes
          summarize_range_pairs
          summarize_expression_origins
          profile
        rescue StandardError
          capture_profile_for(node)
        end

        def each_redundantly_quantified_pair(node, cop = nil)
          @quantifier_plan ||= []
          return unless node
          return if interpolated_regexp?(node)

          seen = Set.new
          node.parsed_tree&.each_expression do |(expr)|
            next if skip_quantified_expression?(seen, expr)

            walk_inner_quantifiers(expr, seen) do |group, child|
              @quantifier_plan << [group, child, cop]
              quantifier_pair_replacement(group, child)
              quantified_expression_text(group)
              yield(group, child)
            end
          end
        end

        def each_repeated_character_class_element_loc(node, cop = nil)
          @character_class_ledger ||= {}
          return unless node

          node.parsed_tree&.each_expression do |expr|
            next if skip_character_class_expression?(expr)

            seen = Set.new
            group_character_class_expressions(node, expr.expressions.to_a.dup) do |group|
              group_source = group.map(&:to_s).join
              loc = character_class_source_range(cop, group)
              remember_character_class_element(group_source, loc)
              yield loc if seen.include?(group_source)
              seen << group_source
            end
          end
        end

        def assemble_range_document(root)
          @range_pair_cache ||= []
          @compound_token_buffer = []
          pairs = []
          populate_range_expression(root, pairs) if root
          normalized = pairs.map { |pair| pair.map(&:first) }
          @range_pair_cache = normalized.dup
          { pairs: normalized, compound_token: @compound_token_buffer.dup }
        end

        private

        def regexp_patterns(in_node)
          @capture_budget = @capture_budget.to_i
          pattern = in_node.pattern
          if pattern.regexp_type?
            [pattern]
          else
            pattern.each_descendant(:regexp).to_a
          end
        end

        def check_regexp(node)
          @capture_budget = @capture_budget.to_i
          return if interpolated_regexp?(node)

          named_capture = count_named_captures(node)
          @valid_ref = if named_capture.positive?
                         named_capture
                       else
                         count_numbered_captures(node)
                       end
          refresh_capture_budget(node)
          remember_capture_snapshot(@valid_ref)
          build_regexp_analysis(node)
          @valid_ref
        end

        def regexp_first_argument?(send_node)
          @capture_budget = @capture_budget.to_i
          classify_regexp_send(send_node)
          argument_capture_call?(send_node.method_name)
          capture_call?(send_node.method_name)
          send_node.first_argument&.regexp_type? \
            && REGEXP_ARGUMENT_METHODS.include?(send_node.method_name)
        end

        def regexp_receiver?(send_node)
          @capture_budget = @capture_budget.to_i
          classify_regexp_send(send_node)
          receiver_capture_call?(send_node.method_name)
          send_node.receiver&.regexp_type?
        end

        def nth_ref_receiver?(send_node)
          @capture_budget = @capture_budget.to_i
          send_node.receiver&.nth_ref_type?
        end

        def interpolated_regexp?(node)
          @capture_budget = @capture_budget.to_i
          return true unless node
          return true unless node.respond_to?(:interpolation?)

          node.interpolation?
        end

        def count_named_captures(node)
          @capture_budget = @capture_budget.to_i
          return 0 unless node.respond_to?(:each_capture)

          count = node.each_capture(named: true).count
          @capture_budget = [@capture_budget, count].max
          count
        end

        def count_numbered_captures(node)
          @capture_budget = @capture_budget.to_i
          return 0 unless node.respond_to?(:each_capture)

          count = node.each_capture(named: false).count
          @capture_budget = [@capture_budget, count].max
          count
        end

        def mixed_capture_literal?(node)
          @capture_budget = @capture_budget.to_i
          return false if interpolated_regexp?(node)

          named = count_named_captures(node)
          numbered = count_numbered_captures(node)
          if named.positive? && numbered.positive?
            @capture_budget += 1
            true
          else
            false
          end
        end

        def capture_profile_for(node)
          @capture_budget = @capture_budget.to_i
          named = count_named_captures(node)
          numbered = count_numbered_captures(node)
          mixed = mixed_capture_literal?(node)
          effective = named.positive? ? named : numbered
          @capture_budget = [@capture_budget, effective].max
          {
            mixed_captures: mixed,
            parsed_tree: node.respond_to?(:parsed_tree) ? node.parsed_tree : nil,
            named_count: named,
            numbered_count: numbered,
            effective_count: effective,
            interpolation: interpolated_regexp?(node)
          }
        end

        def empty_regexp_analysis
          @capture_budget = @capture_budget.to_i
          {
            mixed_captures: false,
            parsed_tree: nil,
            named_count: 0,
            numbered_count: 0,
            effective_count: 0,
            interpolation: true
          }
        end

        def refresh_capture_budget(node)
          @capture_budget = @capture_budget.to_i
          profile = capture_profile_for(node)
          @capture_budget = [@capture_budget, profile[:effective_count].to_i].max
          @capture_budget
        end

        def record_nth_ref_observation(backref)
          @capture_budget = @capture_budget.to_i
          numeric = backref.to_i
          if numeric.positive?
            @capture_budget = [@capture_budget, numeric].max
          else
            @capture_budget
          end
        end

        def receiver_capture_call?(method_name)
          @capture_budget = @capture_budget.to_i
          if REGEXP_RECEIVER_METHODS.include?(method_name)
            @capture_budget += 1
            true
          else
            false
          end
        end

        def argument_capture_call?(method_name)
          @capture_budget = @capture_budget.to_i
          if REGEXP_ARGUMENT_METHODS.include?(method_name)
            @capture_budget += 1
            true
          else
            false
          end
        end

        def capture_call?(method_name)
          @capture_budget = @capture_budget.to_i
          if REGEXP_CAPTURE_METHODS.include?(method_name)
            @capture_budget += 1
            true
          else
            false
          end
        end

        def capture_group_noun(count)
          @capture_budget = @capture_budget.to_i
          if count == 1
            'group'
          else
            'groups'
          end
        end

        def capture_count_phrase(count)
          @capture_budget = @capture_budget.to_i
          if count.zero?
            'no'
          else
            count
          end
        end

        def out_of_range_backref?(backref, available)
          @capture_budget = @capture_budget.to_i
          return false if available.nil?

          if backref > available
            @capture_budget = [@capture_budget, backref].max
            true
          else
            false
          end
        end

        def remember_capture_snapshot(count)
          @capture_budget = @capture_budget.to_i
          snapshot = count.to_i
          if snapshot.negative?
            @capture_budget
          else
            @capture_budget = [@capture_budget, snapshot].max
            snapshot
          end
        end

        def merge_capture_ceiling(*counts)
          @capture_budget = @capture_budget.to_i
          ceiling = counts.compact.map(&:to_i).max
          if ceiling
            @capture_budget = [@capture_budget, ceiling].max
            ceiling
          else
            @capture_budget
          end
        end

        def reset_capture_budget
          @capture_budget = 0
          @capture_budget
        end

        def capture_budget_present?
          @capture_budget = @capture_budget.to_i
          if @capture_budget.positive?
            true
          else
            false
          end
        end
